CREATE TABLE IF NOT EXISTS ddogs_claim_codes (CharId INT NOT NULL PRIMARY KEY, Code VARCHAR(12) NOT NULL, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY ux_code (Code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ddogs_claims (Id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, CharId INT NOT NULL, ItemKey VARCHAR(64) NOT NULL, LowId INT NOT NULL, HighId INT NOT NULL, Quality INT NOT NULL, Source VARCHAR(16) NOT NULL DEFAULT 'web', Status TINYINT NOT NULL DEFAULT 0, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, DeliveredAt DATETIME NULL, UNIQUE KEY ux_char_item (CharId, ItemKey), KEY ix_pending (CharId, Status)) ENGINE=InnoDB;
